SET plan_cache_mode=force_custom_plan; SET statement_timeout=120000; PREPARE hfs1579 AS SELECT r.id, r.version_id, r.data, r.last_updated, r.fhir_version, r.last_updated AS sort_key FROM ( SELECT DISTINCT resource_id, last_updated FROM search_index WHERE tenant_id = $1 AND resource_type = $2 AND param_name = 'code' AND ((value_token_system IN ($3, 'urn:x-helios:implicit code system') AND value_token_code = $4)) ORDER BY last_updated DESC, resource_id ASC LIMIT 1001 ) c JOIN resources r ON r.tenant_id = $1 AND r.resource_type = $2 AND r.id = c.resource_id WHERE r.is_deleted = FALSE ORDER BY c.last_updated DESC, c.resource_id ASC;
EXPLAIN (ANALYZE, BUFFERS, FORMAT JSON) EXECUTE hfs1579('default','Observation','http://loinc.org','8302-2');
